<script setup>
import { ref, reactive, computed, onMounted, watch } from 'vue'
import { useWorkspace } from '../application/useWorkspace'
import { localDate, hours, roleLabel, shiftRows } from '../domain/calendar'

const props = defineProps({ user: { type: Object, required: true } })
const w = useWorkspace(props.user)
const { isAdmin, companies, directory, invitations, companyId, members, shifts, applications, freelancers, profile, accounts, requests, restriction, busy, loading, error, message, current, manager, canSchedule, repo } = w
const tab = ref(isAdmin ? 'approval' : 'calendar'), month = ref(new Date(new Date().getFullYear(), new Date().getMonth(), 1)), modal = ref('')
const form = reactive({ company_name: '', address: '', phone: '', email: '' }), freelancer = reactive({ display_name: props.user.user_metadata?.full_name || '', specialty: '', visible: false })
const inviteEmail = ref(''), memberEmail = ref(''), reasons = reactive({})
const shift = reactive({ title: '', location: '', date: localDate(new Date()), end_date: localDate(new Date()), start: '08:00', end: '12:00', user_ids: [] })
const role = computed(() => isAdmin ? 'admin' : manager.value ? 'manager' : 'staff')
const tabs = computed(() => isAdmin ? [['approval','Duyệt công ty'],['accounts','Tài khoản'],['calendar','Lịch làm việc'],['people','Thành viên'],['attendance','Giờ công']] : [['calendar','Lịch làm việc'],['attendance','Giờ công'],['people','Thành viên'],['community','Cộng đồng'],['registration','Đăng ký công ty']])
const days = computed(() => { const year = month.value.getFullYear(), m = month.value.getMonth(), offset = (new Date(year,m,1).getDay()+6)%7, count = new Date(year,m+1,0).getDate(); return [...Array(offset).fill(null), ...Array.from({length:count},(_,i)=>i+1)] })
const nameOf = id => members.value.find(m => m.user_id === id)?.full_name || 'Nhân viên'
const shiftsOn = day => shifts.value.filter(s => localDate(new Date(s.starts_at)) === localDate(new Date(month.value.getFullYear(),month.value.getMonth(),day)))
const dayLabel = day => `Ngày ${day}${canSchedule.value ? ', thêm ca' : ''}. ${shiftsOn(day).map(s => `${new Date(s.starts_at).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})} ${s.title}, ${canSchedule.value ? nameOf(s.user_id) : s.location || ''}`).join('; ')}`
const statusText = status => ({pending:'Đang chờ duyệt', approved:'Đã duyệt', rejected:'Đã từ chối'})[status] || status
function changeMonth(delta) { month.value = new Date(month.value.getFullYear(), month.value.getMonth() + delta, 1) }
function openShift(day) { if (!canSchedule.value) return; const date = localDate(new Date(month.value.getFullYear(),month.value.getMonth(),day)); Object.assign(shift,{title:'',location:'',date,end_date:date,start:'08:00',end:'12:00',user_ids:[]}); modal.value='shift' }
function setPeriod(event) { const t = {morning:['08:00','12:00'],afternoon:['13:00','17:00'],evening:['18:00','23:00'],all:['08:00','23:00']}[event.target.value]; if(t) [shift.start,shift.end]=t }
async function perform(fn, success, close = false) { if (await w.perform(fn,success) && close) modal.value='' }
function saveShift() { perform(() => repo.insert('company_shifts', shiftRows(shift,companyId.value)), 'Đã phân ca.', true) }
function saveApplication() { perform(() => repo.insert('company_applications',{...form, applicant_id:props.user.id}), 'Đã gửi đăng ký công ty.') }
function saveProfile() { perform(() => repo.upsert('freelancer_profiles',{user_id:props.user.id,...freelancer}), 'Đã lưu hồ sơ freelancer.') }
function changeCompany() { w.perform(() => Promise.resolve(), '') }
watch(profile, p => { if(p) Object.assign(freelancer, {display_name:p.display_name,specialty:p.specialty,visible:p.visible}) })
onMounted(() => w.perform(() => Promise.resolve(), ''))
</script>

<template>
  <main v-if="loading" class="auth-screen" aria-live="polite">Đang tải dữ liệu...</main>
  <main v-else-if="restriction?.disabled" class="auth-screen"><section class="auth-box"><h1>Tài khoản đã bị vô hiệu hóa</h1><p>Lý do: {{ restriction.reason }}</p><button @click="repo.auth.signOut()">Đăng xuất</button></section></main>
  <div v-else class="app-shell">
    <aside class="sidebar">
      <div class="brand"><span class="brand-mark">S</span><div><strong>SHIFTLY</strong><small>Quản lý nhân sự sự kiện</small></div></div>
      <div class="side-label">KHÔNG GIAN LÀM VIỆC</div>
      <nav aria-label="Điều hướng chính"><button v-for="item in tabs" :key="item[0]" :class="{selected:tab===item[0]}" @click="tab=item[0]">{{ item[1] }}</button></nav>
      <div class="side-bottom"><div class="initial">{{ (user.user_metadata?.full_name || user.email || 'S').slice(0,1).toUpperCase() }}</div><div><b>{{ roleLabel(role) }}</b><small>{{ user.email }}</small></div></div>
    </aside>
    <div class="main-area">
      <header class="topbar"><div><span class="top-brand">SHIFTLY</span><span class="top-title">{{ tabs.find(t => t[0]===tab)?.[1] }}</span></div><button class="text-button" @click="repo.auth.signOut()">Đăng xuất</button></header>
      <nav class="mobile-nav" aria-label="Điều hướng trên điện thoại"><button v-for="item in tabs" :key="item[0]" :class="{selected:tab===item[0]}" @click="tab=item[0]">{{ item[1] }}</button></nav>
      <main class="content">
        <div class="page-heading"><div><p class="eyebrow">{{ roleLabel(role) }}</p><h1>{{ tabs.find(t => t[0]===tab)?.[1] }}</h1><p>Quản lý lịch và đội ngũ của bạn tại một nơi.</p></div><label v-if="companies.length" class="company-select">Công ty<select v-model="companyId" @change="changeCompany"><option v-for="c in companies" :key="c.id" :value="c.id">{{ c.name }}</option></select></label></div>
        <div v-if="error" class="alert" role="alert">{{ error }}</div><div v-if="message" class="notice" role="status">{{ message }}</div>
        <section v-if="invitations.length" class="surface section"><h2>Lời mời tham gia</h2><div v-for="i in invitations" :key="i.id" class="row"><span>{{ directory.find(c=>c.id===i.company_id)?.name || 'Công ty' }}</span><button :disabled="busy" @click="perform(()=>repo.rpc('accept_company_invitation',{p_invitation:i.id}),'Đã tham gia công ty.')">Chấp nhận</button></div></section>

        <template v-if="tab==='calendar'">
          <section v-if="!companyId" class="surface empty"><h2>Chưa có công ty</h2><p>Đăng ký công ty hoặc tìm công ty trong mục Cộng đồng.</p></section>
          <template v-else><div class="calendar-controls"><div><h2>{{ month.toLocaleDateString('vi-VN',{month:'long',year:'numeric'}) }}</h2><p>{{ canSchedule ? 'Chọn ngày để thêm ca làm việc.' : 'Các ca được giao cho bạn.' }}</p></div><div class="button-group"><button aria-label="Tháng trước" @click="changeMonth(-1)">‹</button><button @click="month=new Date()">Hôm nay</button><button aria-label="Tháng sau" @click="changeMonth(1)">›</button></div></div>
          <div class="calendar-wrap"><div class="calendar"><div v-for="name in ['T2','T3','T4','T5','T6','T7','CN']" :key="name" class="weekday">{{ name }}</div><div v-for="(day,index) in days" :key="index" class="day" :class="{blank:!day}"><button v-if="day" class="day-button" :aria-label="dayLabel(day)" @click="openShift(day)"><span class="day-number">{{ day }}</span><span v-for="s in shiftsOn(day)" :key="s.id" class="shift-chip">{{ new Date(s.starts_at).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}) }} {{ s.title }}<small>{{ canSchedule ? nameOf(s.user_id) : s.location }}</small></span></button></div></div></div></template>
        </template>

        <section v-if="tab==='attendance'" class="surface section"><div class="section-title"><div><h2>Giờ công theo lịch</h2><p>Giờ dự kiến, không xác nhận nhân viên đã có mặt.</p></div></div><div v-if="!shifts.length" class="empty">Chưa có ca làm việc.</div><div v-for="s in shifts" :key="s.id" class="row"><div><b>{{ s.title }}</b><small>{{ nameOf(s.user_id) }} | {{ new Date(s.starts_at).toLocaleString('vi-VN') }} | {{ s.location }}</small></div><strong>{{ hours(s) }} giờ</strong></div></section>

        <section v-if="tab==='people'" class="surface section"><div class="section-title"><div><h2>Thành viên</h2><p>{{ current?.name || 'Chọn công ty để xem danh sách.' }}</p></div><button v-if="manager" class="primary" @click="modal='invite'">Mời nhân viên</button></div><div v-if="!members.length" class="empty">Chưa có thành viên để hiển thị.</div><div v-for="m in members" :key="m.user_id" class="row"><div><b>{{ m.full_name }}</b><small>{{ m.email }}</small></div><div class="row-actions"><span class="badge">{{ roleLabel(m.role) }}</span><button v-if="isAdmin && m.role!=='manager'" :disabled="busy" @click="perform(()=>repo.rpc('admin_set_company_manager',{p_company:companyId,p_user:m.user_id}),'Đã chuyển quyền quản lý.')">Đặt làm quản lý</button></div></div><form v-if="isAdmin && companyId" class="inline-form" @submit.prevent="perform(()=>repo.rpc('admin_add_company_member',{p_company:companyId,p_email:memberEmail}),'Đã thêm nhân viên.')"><label>Email tài khoản đã đăng nhập<input v-model="memberEmail" type="email" required></label><button :disabled="busy">Thêm nhân viên</button></form></section>

        <section v-if="tab==='approval'" class="surface section"><h2>Đơn đăng ký công ty</h2><p>Kiểm tra thông tin trước khi duyệt.</p><div v-if="!applications.filter(a=>a.status==='pending').length" class="empty">Không có đơn đang chờ duyệt.</div><div v-for="a in applications.filter(a=>a.status==='pending')" :key="a.id" class="row"><div><b>{{ a.company_name }}</b><small>{{ a.address }} | {{ a.phone }} | {{ a.email }}</small></div><div class="row-actions"><button :disabled="busy" @click="perform(()=>repo.rpc('review_company_application',{p_id:a.id,p_approve:false}),'Đã từ chối đơn.')">Từ chối</button><button class="primary" :disabled="busy" @click="perform(()=>repo.rpc('review_company_application',{p_id:a.id,p_approve:true}),'Đã duyệt công ty.')">Duyệt</button></div></div></section>

        <section v-if="tab==='accounts'" class="surface section"><h2>Quản lý tài khoản</h2><p>Tài khoản bị vô hiệu hóa sẽ mất quyền truy cập toàn hệ thống.</p><div v-for="a in accounts.filter(a=>a.user_id!==user.id)" :key="a.user_id" class="row account-row"><div><b>{{ a.full_name }}</b><small>{{ a.email }} | {{ a.disabled ? 'Đã vô hiệu hóa: '+a.reason : 'Đang hoạt động' }}</small></div><label>Lý do<input v-model="reasons[a.user_id]" minlength="5" maxlength="500" placeholder="Ít nhất 5 ký tự"></label><button :disabled="busy" @click="perform(()=>repo.rpc('admin_set_account_disabled',{p_user:a.user_id,p_disabled:!a.disabled,p_reason:reasons[a.user_id]||''}),a.disabled?'Đã kích hoạt tài khoản.':'Đã vô hiệu hóa tài khoản.')">{{ a.disabled?'Kích hoạt':'Vô hiệu hóa' }}</button></div></section>

        <template v-if="tab==='community'"><section class="surface section"><h2>Công ty</h2><p>Tìm công ty và gửi yêu cầu tham gia.</p><div v-if="!directory.length" class="empty">Chưa có công ty.</div><div v-for="c in directory" :key="c.id" class="row"><div><b>{{ c.name }}</b><small>{{ c.address }} | {{ c.phone }}</small></div><button v-if="!companies.some(x=>x.id===c.id)" :disabled="busy" @click="perform(()=>repo.rpc('request_company_membership',{p_company:c.id}),'Đã gửi yêu cầu tham gia.')">Xin tham gia</button><span v-else class="badge">Đã tham gia</span></div></section>
          <section v-if="manager" class="surface section"><h2>Yêu cầu tham gia</h2><div v-if="!requests.length" class="empty">Chưa có yêu cầu đang chờ.</div><div v-for="r in requests" :key="r.user_id" class="row"><b>{{ r.full_name }}</b><div class="row-actions"><button :disabled="busy" @click="perform(()=>repo.rpc('review_join_request',{p_company:companyId,p_user:r.user_id,p_approve:false}),'Đã từ chối.')">Từ chối</button><button :disabled="busy" @click="perform(()=>repo.rpc('review_join_request',{p_company:companyId,p_user:r.user_id,p_approve:true}),'Đã chấp nhận.')">Chấp nhận</button></div></div></section>
          <section v-if="manager" class="surface section"><h2>Freelancer</h2><div v-if="!freelancers.length" class="empty">Chưa có hồ sơ công khai.</div><div v-for="f in freelancers" :key="f.user_id" class="row"><div><b>{{ f.display_name }}</b><small>{{ f.specialty }}</small></div><button :disabled="busy" @click="perform(()=>repo.rpc('invite_freelancer',{p_company:companyId,p_user:f.user_id}),'Đã tạo lời mời.')">Mời</button></div></section>
          <section class="surface section"><h2>Hồ sơ freelancer</h2><form class="form" @submit.prevent="saveProfile"><label>Tên hiển thị<input v-model="freelancer.display_name" required minlength="2" maxlength="100"></label><label>Chuyên môn<input v-model="freelancer.specialty" required minlength="2" maxlength="200" placeholder="Âm thanh, ánh sáng..."></label><label class="check"><input v-model="freelancer.visible" type="checkbox"> Cho quản lý tìm thấy hồ sơ của tôi</label><div><button class="primary" :disabled="busy">Lưu hồ sơ</button></div></form></section></template>

        <section v-if="tab==='registration'" class="surface section form-section"><h2>Đăng ký công ty</h2><p>Thông tin sẽ được gửi quản trị viên duyệt. Sau khi duyệt bạn là quản lý công ty.</p><form class="form" @submit.prevent="saveApplication"><label>Tên công ty<input v-model.trim="form.company_name" required minlength="3" maxlength="120" pattern=".*[\p{L}].*" title="Tên phải có chữ"></label><label>Địa chỉ<input v-model.trim="form.address" required minlength="8" maxlength="250" pattern=".*[\p{L}].*" title="Địa chỉ phải có chữ"></label><div class="form-grid"><label>Số điện thoại Việt Nam<input v-model="form.phone" required inputmode="numeric" pattern="0[0-9]{9}" title="10 chữ số, bắt đầu bằng 0"></label><label>Email công ty<input v-model.trim="form.email" required type="email" maxlength="254"></label></div><div><button class="primary" :disabled="busy">Gửi duyệt</button></div></form><div v-for="a in applications" :key="a.id" class="row"><b>{{ a.company_name }}</b><span class="badge">{{ statusText(a.status) }}</span></div></section>
      </main>
    </div>
    <div v-if="modal" class="overlay" @click.self="modal=''" @keydown.esc="modal=''"><section class="dialog" role="dialog" aria-modal="true" :aria-label="modal==='shift'?'Phân ca làm việc':'Mời nhân viên'"><div class="dialog-heading"><h2>{{ modal==='shift'?'Phân ca làm việc':'Mời nhân viên' }}</h2><button aria-label="Đóng" @click="modal=''">×</button></div><div v-if="error" class="alert" role="alert">{{ error }}</div><form v-if="modal==='invite'" class="form" @submit.prevent="perform(()=>repo.insert('company_invitations',{company_id:companyId,email:inviteEmail.trim().toLowerCase()}),'Đã tạo lời mời.',true)"><label>Email nhân viên<input v-model="inviteEmail" required type="email"></label><p>Nhân viên đăng nhập bằng email được mời để chấp nhận.</p><div class="form-actions"><button type="button" @click="modal=''">Hủy</button><button class="primary" :disabled="busy">Gửi lời mời</button></div></form>
      <form v-else class="form" @submit.prevent="saveShift"><label>Công việc / sự kiện<input v-model="shift.title" required maxlength="200"></label><label>Địa điểm<input v-model="shift.location" required maxlength="250"></label><div class="form-grid"><label>Ngày bắt đầu<input v-model="shift.date" type="date" required @change="shift.end_date=shift.date"></label><label>Buổi<select @change="setPeriod"><option value="morning">Sáng</option><option value="afternoon">Chiều</option><option value="evening">Tối</option><option value="all">Cả ngày</option><option value="custom">Tự chọn</option></select></label><label>Bắt đầu<input v-model="shift.start" type="time" required></label><label>Kết thúc<input v-model="shift.end" type="time" required></label></div><label>Ngày kết thúc<input v-model="shift.end_date" type="date" required></label><fieldset><legend>Nhân viên</legend><label v-for="m in members" :key="m.user_id" class="check"><input v-model="shift.user_ids" :value="m.user_id" type="checkbox">{{ m.full_name }} ({{ m.email }})</label><small v-if="!members.length">Chưa có thành viên để phân ca.</small></fieldset><div class="form-actions"><button type="button" @click="modal=''">Hủy</button><button class="primary" :disabled="busy">Lưu phân ca</button></div></form>
    </section></div>
  </div>
</template>
